mapper.select:
SELECT * FROM (

    SELECT o.*, '${t}' AS src FROM t_order_${t} o WHERE 1 = 1 

) x ORDER BY created_at DESC, id DESC LIMIT #{q.offset}, #{q.size}

SELECT COALESCE(SUM(c), 0) FROM (

    SELECT COUNT(*) c FROM t_order_${t} o WHERE 1 = 1 

) x

SELECT status, SUM(c) AS cnt FROM (

    SELECT status, COUNT(*) c FROM t_order_${t} WHERE 1 = 1
     AND user_id = #{userId}
    GROUP BY status

) x GROUP BY status

SELECT d AS day, status, SUM(c) AS cnt, SUM(amt) AS amount FROM (

    SELECT DATE_FORMAT(created_at, '%Y-%m-%d') d, status, COUNT(*) c, SUM(pay_amount) amt
    FROM t_order_${t} WHERE created_at >= #{from}
    GROUP BY d, status

) x GROUP BY d, status

